const fs=require('fs'),path=require('path');
module.exports=()=>{const sources={};function collect(n){if(sources[n])return;const s=fs.readFileSync(path.join(__dirname,n+'.js'),'utf8');sources[n]=s;for(const m of s.matchAll(/require\('\.\/([^']+)'\)/g))collect(m[1]);}collect('delete-transaction');return `const deletion=(()=>{const sources=${JSON.stringify(sources)},cache={};function load(n){if(cache[n])return cache[n].exports;const m={exports:{}};cache[n]=m;new Function('require','module','exports',sources[n])(s=>s.startsWith('./')?load(s.slice(2)):require(s),m,m.exports);return m.exports;}return load('delete-transaction');})();`;};
